/**
 * #754 — ACCEPTANCE: a two-sided (flip) 3D part. An ergonomic mouse shell is roughed and
 * ball-finished on side 1, the blank is turned over on two locating pins, and the inside is
 * hollowed on side 2. Real testing: every program here is generated by the app's own CAM, and
 * the cut surface is swept through the flat column engine and compared with the shell's closed
 * form, which owes nothing to the CAM or the sweep.
 *
 * THE PART. A shell over an elliptical footprint (a × b half-axes), its crown leaning to the back
 * like a mouse: zOut(x, y) = H · √(1 − u²) · (0.85 + 0.15 · x / a), u² = (x/a)² + (y/b)². The
 * inside is the outside lowered by exactly the wall `W` (a vertical offset), so the designed
 * vertical wall is W wherever the shell stands W proud of its rim plane — every probe here.
 *
 * THE FLIP. Side 2 turns the blank over about the line y = CY (an axis along X through the part's
 * centre): a point (x, y) of side 1 sits at (x, 2·CY − y) on side 2. The pins lie ON that line,
 * so each lands in its own hole after the turn, and at unequal distances from the part's centre,
 * so a blank also spun 180° about Z cannot sit on them (the mistake the pins exist to stop).
 *
 * WHAT IS NOT YET THE APP'S. One job does not carry both sides with the pins as their datum
 * (#723 part 2): here the two sides are two jobs and the test does the flip transform. That gap
 * is stated as a `todo`, not faked.
 */
import { afterEach, describe, expect, it } from 'vitest';

const backing = new Map<string, string>();
(globalThis as unknown as { localStorage: Storage }).localStorage = {
  getItem: (k: string) => backing.get(k) ?? null,
  setItem: (k: string, v: string) => void backing.set(k, String(v)),
  removeItem: (k: string) => void backing.delete(k),
  clear: () => backing.clear(),
  key: (i: number) => [...backing.keys()][i] ?? null,
  get length() {
    return backing.size;
  },
} as Storage;

import {
  generateSurface3dIR,
  moldHeightfield,
  sampleGoalHeightfield,
  type GoalHeightfield,
  type SurfaceFeeds,
  type SurfaceTool,
} from '@/engine/cnc/cam/surface3d';
import { clearTargetObjectMeshCache } from '@/engine/import/targetObject';
import { generateGoalProgram } from '@/workers/sim/engraveGenerate';
import { defaultEngraveJob } from '@/engine/cnc/engrave/defaults';
import { flatEndMill } from '@/engine/cnc/tool';
import type { EngraveJob, EngraveTargetObject } from '@/types/engraveJob';
import type { RapidEstimate, CamMove } from '@/engine/cnc/cam/ir';
import { FLAT, type ColumnCutter, type CutMove } from '@/workers/geometry/columnEngine';
import { stubSetup, type Setup } from '@/engine/cnc/setup';
import { rectProfile } from '@/engine/compiler/profile';

afterEach(() => clearTargetObjectMeshCache());

type V = [number, number, number];
type Tri = [V, V, V];

// ── The part and the blank ──────────────────────────────────────────────────────────────────────
const A = 30; // half-length, mm (a 60 mm mouse)
const B = 17; // half-width, mm (34 mm)
const H = 20; // crown height above the rim plane, mm
const W = 2.5; // wall, mm
const BLANK = { length: 80, width: 50, thickness: 26 };
const CX = 40;
const CY = 25; // the part's centre, on the flip line
/** The two locating pins: on the flip line, at unequal distances from the centre. */
const PINS = [
  { x: 4, y: CY },
  { x: 75, y: CY },
];

/** Shell height above its rim plane at local (x, y); 0 outside the footprint. */
function shell(a: number, b: number, h: number, x: number, y: number): number {
  const u2 = (x / a) ** 2 + (y / b) ** 2;
  if (u2 >= 1) return 0;
  return h * Math.sqrt(1 - u2) * (0.85 + 0.15 * (x / a));
}
const zOut = (x: number, y: number): number => shell(A, B, H, x, y);
/** The inside: the outside lowered by exactly W, so the vertical wall is W wherever the shell stands W proud. */
const zIn = (x: number, y: number): number => Math.max(0, zOut(x, y) - W);
/** A surface's crown (where the lean puts it): the mesh's top, placed at the blank's Z 0. */
const crownOf = (f: (x: number, y: number) => number): number => {
  let best = 0;
  for (let i = 0; i <= 400; i++) best = Math.max(best, f((i / 400) * A, 0));
  return best;
};

/** A surface over the footprint as triangles, local frame, rim plane at z = 0. */
function surfaceTris(f: (x: number, y: number) => number, seg = 64): Tri[] {
  const at = (r: number, t: number): V => {
    const x = A * r * Math.cos(2 * Math.PI * t);
    const y = B * r * Math.sin(2 * Math.PI * t);
    return [x, y, f(x, y)];
  };
  const tris: Tri[] = [];
  for (let i = 0; i < seg; i++) {
    for (let j = 0; j < seg; j++) {
      const p = at(i / seg, j / seg);
      const q = at((i + 1) / seg, j / seg);
      const r = at((i + 1) / seg, (j + 1) / seg);
      const s = at(i / seg, (j + 1) / seg);
      tris.push([p, q, r], [p, r, s]);
    }
  }
  return tris;
}

function stl(tris: Tri[]): string {
  const buf = new ArrayBuffer(84 + tris.length * 50);
  const dv = new DataView(buf);
  dv.setUint32(80, tris.length, true);
  let off = 84;
  for (const t of tris) {
    off += 12;
    for (const v of t) {
      dv.setFloat32(off, v[0], true);
      dv.setFloat32(off + 4, v[1], true);
      dv.setFloat32(off + 8, v[2], true);
      off += 12;
    }
    off += 2;
  }
  return Buffer.from(new Uint8Array(buf)).toString('base64');
}

let serial = 0;
function goal(f: (x: number, y: number) => number, over: Partial<EngraveTargetObject> = {}): EngraveTargetObject {
  return {
    id: 'shell',
    name: 'mouse-shell.stl',
    format: 'stl',
    sha256: (serial++).toString(16).padStart(64, 'c'),
    data: stl(surfaceTris(f)),
    size: { x: 2 * A, y: 2 * B, z: crownOf(f) },
    position: { x: CX, y: CY, z: 0 },
    rotation: 0,
    enabled: true,
    role: 'goal',
    ...over,
  };
}

// ── The cutters and the sweep ───────────────────────────────────────────────────────────────────
const RAPID: RapidEstimate = { xyMmPerMin: 1200, zMmPerMin: 600, accelMmPerS2: 150, source: 'test' };
/** Makera's ⌀3 ball nose (the full catalogue is assumed for demo and test jobs). */
const BALL_R = 1.5;
const BALL: SurfaceTool = { radius: BALL_R, ball: true };
const BALL_TOOL = flatEndMill(2 * BALL_R, { shape: 'ball', name: '3 mm ball nose' });
const BALL_CUTTER: ColumnCutter = { radius: 0, tanHalf: null, cornerRadius: BALL_R, outerRadius: BALL_R };
const FINISH_STEP = 0.3;
const FEEDS: SurfaceFeeds = { feed: 900, plungeFeed: 300, stepDown: 1.5, roughStepOver: 1.2, finishStepOver: FINISH_STEP };
const PITCH = 0.25;

function prism(w: number, d: number, t: number): Setup {
  return stubSetup({ kind: 'prism', outline: rectProfile(w, d), thickness: t }, { kind: 'tape-down', contact: rectProfile(w, d) });
}

function sweep(moves: readonly CamMove[]): ReturnType<typeof FLAT.buildGrid> {
  const cut: CutMove[] = [];
  for (let i = 1; i < moves.length; i++) {
    const a = moves[i - 1]!;
    const b = moves[i]!;
    if (b.kind !== 'feed') continue;
    cut.push({ step: i, line: i, u0: a.x, u1: b.x, v0: a.y, v1: b.y, z: Math.min(a.z, b.z) });
  }
  const grid = FLAT.buildGrid(prism(BLANK.length, BLANK.width, BLANK.thickness), BALL_CUTTER, cut, {
    dx: PITCH,
    dThetaDeg: PITCH,
  });
  for (const m of cut) FLAT.applyMove(grid, m, BALL_CUTTER);
  return grid;
}

function heightAt(grid: ReturnType<typeof FLAT.buildGrid>, x: number, y: number): number {
  const i = Math.round((x - grid.u0) / grid.du);
  const j = Math.round((y - grid.v0) / grid.dv);
  return grid.h[j * grid.nu + i] as number;
}

function finishOf(hf: GoalHeightfield) {
  return generateSurface3dIR({
    heightfield: hf,
    tool: BALL,
    toolObj: BALL_TOOL,
    toolNumber: 1,
    spindleRpm: 16000,
    air: true,
    feeds: FEEDS,
    rapid: RAPID,
    labelId: 'shell',
  });
}

/**
 * The band a ball finish may leave above the true surface: the scallop between two passes at the
 * step-over on a flat, grown by the surface's slope (a pass's spacing measured along a steep wall
 * is longer than across), plus one sample cell either side for the two grids' quantisation.
 */
const SCALLOP = BALL_R - Math.sqrt(BALL_R ** 2 - (FINISH_STEP / 2) ** 2);
const SAMPLE_SLOP = 2 * PITCH;

/** Interior points, local to the part's centre, kept off the steep rim where a ball cannot reach. */
const PROBES: [number, number][] = [
  [0, 0],
  [8, 0],
  [-10, 0],
  [15, 4],
  [-15, -4],
  [5, 8],
  [-5, -8],
  [20, 0],
];

function job(target: EngraveTargetObject): EngraveJob {
  return {
    ...defaultEngraveJob(),
    labels: [],
    shapes: [],
    stock: { ...defaultEngraveJob().stock, ...BLANK },
    targetObject: target,
  };
}

// ── Side 1 ──────────────────────────────────────────────────────────────────────────────────────
describe('#754 side 1 — the outside of the shell, roughed and ball-finished', () => {
  it('generates as one job: roughing, then the ball finish and its scallop pass', () => {
    const j = job(goal(zOut, { surface: { finishStepOverMm: FINISH_STEP, scallop: true } }));
    const out = generateGoalProgram(j, j.targetObject!, BALL_TOOL, [], null, {});
    expect(out.errors).toEqual([]);
    expect(out.ok).toBe(true);
    // Three operations: the roughing, the parallel ball finish and the scallop pass.
    expect(out.programs).toHaveLength(1);
    expect(out.cam!.operations).toBe(3);
    // The deepest cut is the rim plane: the part stands H proud of what is left of the blank.
    let deepest = Infinity;
    for (const m of out.nc!.matchAll(/Z(-?\d+(?:\.\d+)?)/g)) deepest = Math.min(deepest, Number(m[1]));
    expect(deepest).toBeCloseTo(-crownOf(zOut), 0);
  });

  it('the finished surface, swept, matches the shell within a scallop — never below it', () => {
    const hf = sampleGoalHeightfield(goal(zOut), { pitchMm: PITCH });
    const { finishing } = finishOf(hf);
    const grid = sweep(finishing.moves);
    const top = crownOf(zOut);
    for (const [lx, ly] of PROBES) {
      const truth = zOut(lx, ly) - top; // world Z: the crown at the blank's top (Z 0)
      const got = heightAt(grid, CX + lx, CY + ly);
      const slope = Math.hypot(
        (zOut(lx + 0.01, ly) - zOut(lx - 0.01, ly)) / 0.02,
        (zOut(lx, ly + 0.01) - zOut(lx, ly - 0.01)) / 0.02,
      );
      const band = SCALLOP * (1 + slope) + SAMPLE_SLOP * Math.max(1, slope);
      expect(got, `under (${lx}, ${ly}): not cut into the shell`).toBeGreaterThanOrEqual(truth - SAMPLE_SLOP * Math.max(1, slope));
      expect(got, `under (${lx}, ${ly}): within the finish's band`).toBeLessThanOrEqual(truth + band);
    }
  });
});

describe('#754 the mirror finish — a 0.05 mm step-over', () => {
  const fine = () => {
    const j = job(goal(zOut, { surface: { finishStepOverMm: 0.05, scallop: true } }));
    return generateGoalProgram(j, j.targetObject!, BALL_TOOL, [], null, {});
  };

  it('generates: the scallop pass steps 0.05 mm along the surface (a 0.0002 mm cusp for a ⌀3 ball)', () => {
    const out = fine();
    expect(out.errors).toEqual([]);
    expect(out.ok).toBe(true);
    expect(out.surface3d?.finishStepOverMm).toBe(0.05);
    expect(out.surface3d?.scallop?.stepOverMm).toBe(0.05);
    // The theoretical cusp between passes on a flat: r − √(r² − (s/2)²).
    expect(BALL_R - Math.sqrt(BALL_R ** 2 - 0.025 ** 2)).toBeLessThan(0.00025);
  });

  // #755 — the grid follows the finish when it can: a 0.05 mm finish on a ⌀3 ball would need more
  // finishing tip-field evaluations than the run's budget allows, so the job settles at the grid it
  // would have used and STATES that pitch and the cap that bound — never refusing the job.
  it('#755 — a finish step-over finer than the sampled grid is followed or the cap that bound is stated', () => {
    const out = fine();
    expect(out.ok).toBe(true);
    const grid = out.surface3d!.gridPitchMm;
    const stated = out.findings.find((f) => f.code === 'goal-finish-finer-than-grid');
    if (grid > 0.05) {
      expect(stated).toBeDefined();
      expect(stated!.message).toContain('the finish passes are 0.05 mm apart');
      // #785 — three caps can settle the grid: the finishing tip field, the heightfield's cell
      // cap, and the app's stated move budget. The run says WHICH bound.
      expect(stated!.message).toMatch(/tip field|move budget|cells settle the grid/);
    } else {
      expect(stated).toBeUndefined();
    }
  });

  // #755 — and when the heightfield's cell cap binds, the run STATES the pitch it settled on rather
  // than refusing the job (the maintainer's rule: inform, don't refuse).
  it('#755 — a cap-bound grid is stated with the pitch it settled on, not refused', () => {
    const j = job(goal(zOut, { surface: { finishStepOverMm: 0.005, scallop: false } }));
    const out = generateGoalProgram(j, j.targetObject!, BALL_TOOL, [], null, {});
    expect(out.ok).toBe(true);
    const f = out.findings.find((x) => x.code === 'goal-finish-finer-than-grid');
    expect(f).toBeDefined();
    expect(f!.severity).toBe('warning');
    expect(f!.message).toContain('the finish passes are 0.005 mm apart');
    const settled = Number(out.surface3d!.gridPitchMm.toFixed(4));
    expect(f!.message).toContain(`known every ${settled} mm`);
    expect(out.surface3d!.gridPitchMm).toBeGreaterThan(0.005);
  }, 120_000);
});

// ── The pins ────────────────────────────────────────────────────────────────────────────────────
describe('#754 the locating pins', () => {
  const flip = (p: { x: number; y: number }) => ({ x: p.x, y: 2 * CY - p.y });
  const spin = (p: { x: number; y: number }) => ({ x: 2 * CX - p.x, y: 2 * CY - p.y });
  const same = (a: { x: number; y: number }[], b: { x: number; y: number }[]) =>
    a.every((p) => b.some((q) => Math.hypot(p.x - q.x, p.y - q.y) < 1e-9));

  it('each pin lands in its own hole when the blank is turned over about the flip line', () => {
    expect(same(PINS.map(flip), PINS)).toBe(true);
  });

  it('a blank also spun 180° about Z does NOT sit on them — the mistake the pins exist to stop', () => {
    expect(same(PINS.map(spin), PINS)).toBe(false);
    // And the pins clear the part and its finishing reach, inside the blank.
    for (const p of PINS) {
      expect(Math.abs(p.x - CX)).toBeGreaterThan(A + BALL_R + 2);
      expect(p.x).toBeGreaterThan(3);
      expect(p.x).toBeLessThan(BLANK.length - 3);
    }
  });
});

// ── Side 2 ──────────────────────────────────────────────────────────────────────────────────────
describe('#754 side 2 — turned over on the pins, the inside hollowed', () => {
  /**
   * Side 2's top is side 1's bottom, faced down to the rim plane (BLANK.thickness − crown). The
   * hollow is the INSIDE form made as a mold — a cavity — and the mold's turn-over about X at CY
   * is exactly the flip about the pin line, so a point (x, y) of side 1 is (x, 2·CY − y) here.
   */
  const innerTop = crownOf(zIn);

  it('generates the hollow as a mold of the inside form', () => {
    const j = job(goal(zIn, { goalMode: 'mold', surface: { finishStepOverMm: FINISH_STEP } }));
    const out = generateGoalProgram(j, j.targetObject!, BALL_TOOL, [], null, {});
    expect(out.errors).toEqual([]);
    expect(out.ok).toBe(true);
    expect(out.findings.find((f) => f.code === 'goal-mold-one-sided')?.severity).toBe('info');
  });

  it('leaves at least the wall between the side-1 surface and the side-2 hollow, and not much more', () => {
    const inner = sampleGoalHeightfield(goal(zIn), { pitchMm: PITCH });
    const cavity = moldHeightfield(inner, CY, -innerTop);
    const { finishing } = finishOf(cavity);
    const grid = sweep(finishing.moves);
    for (const [lx, ly] of PROBES) {
      // Side 2's surface is the rim plane: the hollow's depth below it at the FLIPPED point.
      const depth = -heightAt(grid, CX + lx, CY - ly);
      const wall = zOut(lx, ly) - depth; // material left between the outside and the hollow
      const slope = Math.hypot(
        (zIn(lx + 0.01, ly) - zIn(lx - 0.01, ly)) / 0.02,
        (zIn(lx, ly + 0.01) - zIn(lx, ly - 0.01)) / 0.02,
      );
      const band = SCALLOP * (1 + slope) + SAMPLE_SLOP * Math.max(1, slope);
      // The design's own vertical wall here (≥ W under the crown, by the form's construction).
      const designed = zOut(lx, ly) - zIn(lx, ly);
      expect(designed).toBeCloseTo(W, 9);
      expect(wall, `wall under (${lx}, ${ly})`).toBeGreaterThanOrEqual(designed - SAMPLE_SLOP * Math.max(1, slope));
      expect(wall, `wall under (${lx}, ${ly})`).toBeLessThanOrEqual(designed + band);
    }
  });

  it.todo(
    'one job carries both sides with the pins as their datum, and the app does the flip transform (#723 part 2)',
  );
});
